from google.cloud import documentai_v1beta3 as documentai
import os

def extract_invoice_fields(project_id: str, location: str, processor_id: str, file_path: str) -> dict:
    """
    Extracts vendor, date, total, and line-item fields from an invoice using Google Cloud Document AI.
    """
    opts = {"api_endpoint": f"{location}-documentai.googleapis.com"}
    client = documentai.DocumentProcessorServiceClient(client_options=opts)

    name = client.processor_path(project_id, location, processor_id)

    with open(file_path, "rb") as image:
        image_content = image.read()

    raw_document = documentai.RawDocument(content=image_content, mime_type="application/pdf")

    request = documentai.ProcessRequest(name=name, raw_document=raw_document)
    result = client.process_document(request=request)
    document = result.document

    extracted_fields = {
        "vendor_name": None,
        "invoice_date": None,
        "total_amount": None,
        "line_items": []
    }

    for entity in document.entities:
        if entity.type == "vendor_name":
            extracted_fields["vendor_name"] = entity.mention_text
        elif entity.type == "invoice_date":
            extracted_fields["invoice_date"] = entity.mention_text
        elif entity.type == "total_amount":
            extracted_fields["total_amount"] = entity.mention_text
        elif entity.type == "line_item":
            line_item = {}
            for sub_entity in entity.properties:
                if sub_entity.type == "description":
                    line_item["description"] = sub_entity.mention_text
                elif sub_entity.type == "amount":
                    line_item["amount"] = sub_entity.mention_text
            extracted_fields["line_items"].append(line_item)

    return extracted_fields

from azure.ai.formrecognizer import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential
import os

def extract_receipt_fields(endpoint: str, key: str, receipt_path: str) -> dict:
    """
    Extracts merchant, tax, total, and items from a receipt using Azure Form Recognizer.
    """
    document_analysis_client = DocumentAnalysisClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    with open(receipt_path, "rb") as f:
        poller = document_analysis_client.begin_analyze_document(
            "prebuilt-receipt", document=f.read()
        )
    receipts = poller.result()

    extracted_fields = {
        "merchant_name": None,
        "tax_amount": None,
        "total_amount": None,
        "items": []
    }

    for idx, receipt in enumerate(receipts.documents):
        if receipt.fields.get("MerchantName"):
            extracted_fields["merchant_name"] = receipt.fields.get("MerchantName").value
        if receipt.fields.get("TotalTax"):
            extracted_fields["tax_amount"] = receipt.fields.get("TotalTax").value
        if receipt.fields.get("Total"):
            extracted_fields["total_amount"] = receipt.fields.get("Total").value

        if receipt.fields.get("Items"):
            for item in receipt.fields.get("Items").value:
                item_data = {}
                if item.value.get("Description"):
                    item_data["description"] = item.value.get("Description").value
                if item.value.get("TotalPrice"):
                    item_data["total_price"] = item.value.get("TotalPrice").value
                extracted_fields["items"].append(item_data)

    return extracted_fields

